INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (4600093825070129, ARRAY['"[8 marks] Explain and apply Introduction to Plant nutrients in “INTRODUCTION TO FERTILZERS”; include the governing principle, an example and a verification or limitation."'::jsonb, '"[8 marks] Explain and apply Ammonium Nitrate: Properties in “NITROGENOUS FERTILIZERS”; include the governing principle, an example and a verification or limitation."'::jsonb, '"[8 marks] Explain and apply Physical in “POTASSIUM FERTILIZERS”; include the governing principle, an example and a verification or limitation."'::jsonb, '"[8 marks] Explain and apply FERTILIZERS Production Processes of Phosphoric acid in “PHOSPHORUS FERTILIZERS AND POTASH”; include the governing principle, an example and a verification or limitation."'::jsonb]::jsonb[], ARRAY[]::jsonb[], ARRAY['"Model answer (8 marks)\n\n**Meaning (2):** Introduction to Plant nutrients is covered in “INTRODUCTION TO FERTILZERS”. Define it, describe the main steps/components, relate it to Fertilizer specifications, Terminology and Definitions, Application of fertilizers considering Nutrient, Balance and types of crop. Development of fertilizer industry, give an example and mention a check or limitation.\n\n**Principles/steps (3):** Explain the concept and connect it to Fertilizer specifications, Terminology and Definitions, Application of fertilizers considering Nutrient, Balance and types of crop. Development of fertilizer industry.\n\n**Application/example (2):** Apply it to a realistic FERTILIZER TECHNOLOGY task and state the expected result.\n\n**Verification/conclusion (1):** Check the result and mention a relevant limitation or risk.\n\nMarking guide: meaning 2; principles 3; application 2; verification 1."'::jsonb, '"Model answer (8 marks)\n\n**Meaning (2):** Ammonium nitrate is produced by neutralizing nitric acid with ammonia; storage and prilling require safety controls.\n\n**Principles/steps (3):** Explain the concept and connect it to production and storage, Nitric acid: preparation and process flow diagram, Manufacturing of Nitric Acid by Pressure ammonia oxidation process and Intermediate pressure ammonia oxidation process. Urea: Physical, chemical properties.\n\n**Application/example (2):** Apply it to a realistic FERTILIZER TECHNOLOGY task and state the expected result.\n\n**Verification/conclusion (1):** Check the result and mention a relevant limitation or risk.\n\nMarking guide: meaning 2; principles 3; application 2; verification 1."'::jsonb, '"Model answer (8 marks)\n\n**Meaning (2):** Physical is covered in “POTASSIUM FERTILIZERS”. Define it, describe the main steps/components, relate it to chemical properties and uses of Potassium Chloride, Potassium nitrate, Potassium sulphate, Manufacturing of potassium chloride from sylvinite, give an example and mention a check or limitation.\n\n**Principles/steps (3):** Explain the concept and connect it to chemical properties and uses of Potassium Chloride, Potassium nitrate, Potassium sulphate, Manufacturing of potassium chloride from sylvinite.\n\n**Application/example (2):** Apply it to a realistic FERTILIZER TECHNOLOGY task and state the expected result.\n\n**Verification/conclusion (1):** Check the result and mention a relevant limitation or risk.\n\nMarking guide: meaning 2; principles 3; application 2; verification 1."'::jsonb, '"Model answer (8 marks)\n\n**Meaning (2):** Phosphoric acid is an important phosphate-fertilizer intermediate and may be produced by wet-process routes.\n\n**Principles/steps (3):** Explain the concept and connect it to Dihydrate process, Hemihydrate (HH) process, Ammonium Phosphates, Potash Fertilizers.\n\n**Application/example (2):** Apply it to a realistic FERTILIZER TECHNOLOGY task and state the expected result.\n\n**Verification/conclusion (1):** Check the result and mention a relevant limitation or risk.\n\nMarking guide: meaning 2; principles 3; application 2; verification 1."'::jsonb]::jsonb[]);

